第六题（10分）ECF
1.（5 分）以下程序运行时系统调用全部正确执行，`buffer.txt` 文件的内容为
pekinguniv。请给出代码运行后打印输出的结果，并给出程序运行结束后
`buffer.txt`文件的内容。
```
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
int main() {
    char c;
    int file1 = open("buffer.txt", O_RDWR);
    int file2;
    read(file1, &c, 1);
    file2 = dup(file1);
    write(file2, &c, 1);
    printf("1 = %c\n", c);
    int pid = fork() ;
    if (pid == 0) {
        read(file1, &c, 1);
        write(file2, &c, 1);
        printf("2 = %c\n", c);
        read(file1, &c, 1);
        printf("3 = %c\n", c);
        close(file1);
        exit(0);
    } else {
        waitpid(pid, NULL, 0);
        close(file2);
        dup2(file1, file2);
        read(file2, &c, 1);
        write(file2, &c, 1);
        printf("4 = %c\n", c);
    }
    return 0;
}
```

第四题（10分） 链接
考虑如下3个文件：`main.c, fib.c`和`bignat.c`：
```
/* main.c */
void fib (int n);
int main (int argc, char** argv) {
    int n = 0;
    sscanf(argv[1], "%d", &n);
    fib(n);
}
/* fib.c */
#define N 16
static unsigned int ring[3][N];
static void print_bignat(unsigned int* a) {
    int i;
    for (i = N-1; i >= 0; i--)
        printf("%u ", a[i]); /* print a[i] as unsigned int
    */
    printf("\n");
}
void fib (int n) {
    int i, carry;
    from_int(N, 0, ring[0]); /* fib(0) = 0 */
    from_int(N, 1, ring[1]); /* fib(1) = 1 */
    for (i = 0; i <= n-2; i++) {
        carry  =  plus(N,  ring[i%3],  ring[(i+1)%3],
            ring[(i+2)%3]);
        if (carry)
        {  printf("Overflow  at  fib(%d)\n",  i+2);
            exit(0); }
    }
    print_bignat(ring[n%3]);
}
```
另外，假设在文件`bignat.c`中定义了如下两个函数`plus`和`from_int`（具体
定义略）：


```
int plus (int n, unsigned int* a, unsigned int* b, unsigned
int* c);
void from_int (int n, unsigned int k, unsigned int* a);
```
