#define UVPT 0xef400000

// get_pde(va)：获取虚拟地址va对应的页目录项内容
unsigned int get_pde(unsigned int va) {
    unsigned int pdx = (va >> {{blank:pde_shift}}) & {{blank:pde_mask}};
    unsigned int addr = UVPT + ({{blank:pde_uvpt_offset}}) + pdx * 4;
    return *((unsigned int *)(addr));
}

// get_pte(va)：获取虚拟地址va对应的页表项内容
unsigned int get_pte(unsigned int va) {
    unsigned int PGNUM = va >> {{blank:pte_shift}};
    unsigned int addr = {{blank:pte_base}} + PGNUM;
    return *((unsigned int *)(addr));
}
